package com.companion.service.impl;
import com.companion.agent.*;import com.companion.dto.request.AgentRunCreateRequest;import com.companion.dto.response.*;import com.companion.entity.*;import com.companion.service.AgentRunService;import org.springframework.stereotype.Service;import java.util.List;
@Service public class AgentRunServiceImpl implements AgentRunService {private final AgentRunCreationService creation;private final AgentRunLifecycleService lifecycle;private final AgentOrchestrator orchestrator;public AgentRunServiceImpl(AgentRunCreationService c,AgentRunLifecycleService l,AgentOrchestrator o){creation=c;lifecycle=l;orchestrator=o;}
 public AgentRunResponse create(Long u,AgentRunCreateRequest q){AgentRun r=creation.create(u,q);orchestrator.execute(u,r.getId());return get(u,r.getId());}public AgentRunResponse get(Long u,Long id){AgentRun r=lifecycle.requireOwned(u,id);return response(r,lifecycle.steps(id));}public AgentRunResponse resume(Long u,Long id){AgentRun r=lifecycle.requireOwned(u,id);if(!"COMPLETED".equals(r.getStatus())&&!"FAILED".equals(r.getStatus()))orchestrator.execute(u,id);return get(u,id);}
 private AgentRunResponse response(AgentRun r,List<AgentStep> steps){AgentRunResponse x=new AgentRunResponse();x.setId(r.getId());x.setRequestId(r.getRequestId());x.setGoal(r.getGoal());x.setStatus(r.getStatus());x.setCurrentStep(r.getCurrentStep());x.setMaxSteps(r.getMaxSteps());x.setFinalResult(r.getFinalResult());x.setLastErrorCode(r.getLastErrorCode());x.setLastErrorMessage(r.getLastErrorMessage());x.setVersion(r.getVersion());x.setExecutionVersion(r.getExecutionVersion());x.setCreateTime(r.getCreateTime());x.setUpdateTime(r.getUpdateTime());x.setCompletionTime(r.getCompletionTime());x.setSteps(steps.stream().map(this::step).toList());return x;}
 private AgentStepResponse step(AgentStep s){AgentStepResponse x=new AgentStepResponse();x.setId(s.getId());x.setStepNumber(s.getStepNumber());x.setDecisionType(s.getDecisionType());x.setDecisionSummary(s.getDecisionSummary());x.setToolCallId(s.getToolCallId());x.setToolName(s.getToolName());x.setToolArguments(s.getToolArguments());x.setToolResult(s.getToolResult());x.setStatus(s.getStatus());x.setRetryCount(s.getRetryCount());x.setToolAttemptCount(s.getToolAttemptCount());x.setErrorCode(s.getErrorCode());x.setErrorMessage(s.getErrorMessage());x.setCreateTime(s.getCreateTime());x.setUpdateTime(s.getUpdateTime());x.setCompletionTime(s.getCompletionTime());return x;}
}
